{"patch": {"write": {"manifest.json": "{
 "api_version": "harness_package.v1",
 "hooks": [],
 "memory": {
  "enabled": true
 },
 "skills": [
  {
   "name": "mailing-list-sign-ups",
   "path": "skills/mailing-list-sign-ups.md",
   "description": "read when a request ends by asking to add the contact to a mailing list"
  }
 ],
 "tools": [
  {
   "name": "add_contact_note",
   "description": "Add a note to a contact from its plain text; the tool encodes it as the notes endpoint requires.",
   "input_schema": {
    "type": "object",
    "properties": {
     "contact_id": {
      "type": "string",
      "description": "the contact's id"
     },
     "text": {
      "type": "string",
      "description": "the note, as plain text"
     }
    },
    "required": [
     "contact_id",
     "text"
    ]
   },
   "entrypoint": "tools/notes.py:add_contact_note"
  }
 ]
}", "memory.md": "Closing steps. When a request ends by asking you to tag the contact, add that tag to the contact after the main update and before you finish.
When a request ends by naming a new owner for the contact, assign that owner before you finish.
", "skills/owner-changes.md": "Owner changes as a closing step: assign the owner the request names.
"}}}
